const {t}=useI18n()
const link=(row:any)=>{const paths:Record<string,string>={asn:'/asn/detail/',dn:'/dn/detail/',adjustment:'/adjustment/detail/',picking_task:'/picking/detail/',packing_task:'/packing/detail/'};return row.doc_id&&paths[row.doc_type]?paths[row.doc_type]+row.doc_id:null}
